UPDATE t_incident
SET incident_status = #{target}, lifecycle_version = lifecycle_version + 1, status_reason = #{reason}, status_changed_by = #{actor}

  , investigation_started_at = COALESCE(investigation_started_at, NOW(3)), incident_commander = COALESCE(incident_commander, #{commander})
  , resolved_at = NOW(3), resolution_summary = #{summary}
  , closed_at = NOW(3), closure_summary = #{summary}
  , archived_at = NOW(3)

WHERE id = #{id} AND lifecycle_version = #{version}
